            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            dbf.setXIncludeAware(false);
            dbf.setExpandEntityReferences(false);

            DocumentBuilder db = dbf.newDocumentBuilder();

            // Custom ErrorHandler to suppress default [Fatal Error] console output
            db.setErrorHandler(new ErrorHandler() {
                @Override
                public void warning(SAXParseException exception) throws SAXException {}
                @Override
                public void error(SAXParseException exception) throws SAXException { throw exception; }
                @Override
                public void fatalError(SAXParseException exception) throws SAXException { throw exception; }
            });

            Document doc = db.parse(new ByteArrayInputStream(xmlData.getBytes(StandardCharsets.UTF_8)));

            // Inspect all elements to prevent XMLDecoder RCE vectors
            NodeList allElements = doc.getElementsByTagName("*");
            for (int i = 0; i < allElements.getLength(); i++) {
                Element el = (Element) allElements.item(i);

                // Validate class attributes against whitelist
                if (el.hasAttribute("class")) {
                    String className = el.getAttribute("class");
                    if (!isAllowedClass(className)) {
                        throw new SecurityException("Unauthorized class detected in configuration: " + className);
                    }
                }

                // Note: method and field attributes are intentionally NOT blocked here 
                // because XMLDecoder relies on them for standard property setters and constant references.
            }
        } catch (ParserConfigurationException | SAXException | IOException e) {
            throw new IllegalArgumentException("Invalid XML format or structure", e);
        } catch (SecurityException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("XML security validation failed", e);
        }
    }

    /**
     * Checks if a class name is allowed, supporting array types and blocking known RCE vectors.
     */
    private boolean isAllowedClass(String className) {
        if (className == null) return false;
        if (ALLOWED_CLASSES.contains(className)) return true;

        String cn = className;
        // Handle array types like [Ljava.lang.String;
        while (cn.startsWith("[")) {
            cn = cn.substring(1);
        }
        if (cn.startsWith("L") && cn.endsWith(";")) {
            cn = cn.substring(1, cn.length() - 1);
        }

        if (cn.startsWith("com.example.")) return true;
        if (cn.equals("java.beans.XMLDecoder")) return true;

        // Block known dangerous classes
        if (cn.equals("java.lang.Runtime") ||
            cn.equals("java.lang.ProcessBuilder") ||
            cn.equals("java.lang.System") ||
            cn.equals("java.lang.Class") ||
            cn.equals("java.lang.ClassLoader") ||
            cn.startsWith("java.lang.reflect.") ||
            cn.startsWith("java.lang.invoke.") ||
            cn.equals("java.lang.Thread") ||
            cn.equals("java.lang.ThreadGroup") ||
            (cn.startsWith("java.beans.") && !cn.equals("java.beans.XMLDecoder")) ||
            cn.startsWith("javax.script.") ||
            cn.startsWith("java.rmi.") ||
            cn.startsWith("javax.naming.") ||
            cn.startsWith("org.omg.") ||
            cn.startsWith("sun.") ||
            cn.startsWith("com.sun.")) {
            return false;
        }

        // Allow standard safe packages
        if (cn.startsWith("java.lang.") ||
            cn.startsWith("java.util.") ||
            cn.startsWith("java.time.") ||
            cn.startsWith("java.math.") ||
            cn.startsWith("java.io.") ||
            cn.startsWith("java.net.") ||
            cn.startsWith("java.text.") ||
            cn.startsWith("java.sql.") ||
            cn.startsWith("javax.xml.")) {
            return true;
        }

        return false;
    }
}
